sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    if (newValue == 'promo' || newValue == 'secondary_event') {
		// alert(newValue);
        // alert(g_form.getSectionNames());
        g_form.setSectionDisplay('end_tagdetails', true);
		g_form.setMandatory('objective',true);
		g_form.setMandatory('tune_in_language',true);
    } else {
        g_form.setSectionDisplay('end_tagdetails', false);
		g_form.setMandatory('objective',false);
		g_form.setMandatory('tune_in_language',false);
    }


    //Type appropriate comment here, and begin script below

}
